import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百九十章 从感受中解脱出来","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/190第一百九十章 从感受中解脱出来.md","filePath":"meditation/巴利文大藏经/190第一百九十章 从感受中解脱出来.md"}'),_={name:"meditation/巴利文大藏经/190第一百九十章 从感受中解脱出来.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百九十章-从感受中解脱出来" tabindex="-1">第一百九十章 从感受中解脱出来 <a class="header-anchor" href="#第一百九十章-从感受中解脱出来" aria-label="Permalink to &quot;第一百九十章 从感受中解脱出来&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部18相应5经/受经(罗侯罗相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，罗侯罗尊者来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，佛陀对罗侯罗尊者说：“罗侯罗！你是怎么想的？由眼触（眼触解释，见第一百八十九章）生起的感受是永恒存在的，永远保持不变的，还是随时在变化的，无法永恒存在，无法永远保持不变的？</p><p>罗侯罗尊者回答：“世尊，由眼触生起的感受是随时都在变化的，是无法永恒存在的，是无法永远保持不变的。”</p><p>佛陀说：“罗侯罗！由耳触、鼻触、舌触、身触、意触（耳触、鼻触、舌触、身触、意触解释，见第一百八十九章）生起的感受是永恒存在的，永远保持不变的，还是随时在变化的，无法永恒存在，无法永远保持不变的？”</p><p>罗侯罗尊者回答：“世尊，由耳触、鼻触、舌触、身触、意触生起的感受是随时都在变化的，是无法永恒存在的，是无法永远保持不变的。”</p><p>佛陀说：“罗侯罗！已经受到如来教导的圣弟子们，他们将会逐渐的除灭对眼触所生感受、耳触所生感受、鼻触所生感受、舌触所生感受、身触所生感受、意触所生感受的贪欲，他们不会再执着和挂念眼触所生感受、耳触所生感受、鼻触所生感受、舌触所生感受、身触所生感受、意触所生感受，他们从眼触、耳触、鼻触、舌触、身触、意触生起的感受中解脱出来，他们由此证悟了解脱的智慧，证悟了解脱的果位，他们彻底的明白：「从这一世开始已经不会再次的出生在世间。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有轮回的状态，不会再出生在世间了」。”</p><p>佛陀说法后，罗侯罗尊者再次的顶礼佛陀，他随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',9)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
